import os
from fastapi import FastAPI
from pydantic import BaseModel
from llama_index.core import VectorStoreIndex, SimpleDirectoryReader, Settings, StorageContext
from llama_index.llms.ollama import Ollama
from llama_index.embeddings.ollama import OllamaEmbedding
from llama_index.vector_stores.lancedb import LanceDBVectorStore

DOCS  = os.path.expanduser(os.environ.get("RAG_DOCS", "~/rag-docs"))
DBURI = os.path.expanduser("~/.mobilessh/llamaindex/lancedb")
MODEL = os.environ.get("RAG_MODEL", "llama3.1")
EMBED = os.environ.get("RAG_EMBED", "nomic-embed-text")
OLLAMA = os.environ.get("OLLAMA_BASE_URL", "http://127.0.0.1:11434")

Settings.llm = Ollama(model=MODEL, base_url=OLLAMA, request_timeout=120.0)
Settings.embed_model = OllamaEmbedding(model_name=EMBED, base_url=OLLAMA)

def build():
    os.makedirs(DOCS, exist_ok=True)
    vs = LanceDBVectorStore(uri=DBURI, table_name="docs")
    storage = StorageContext.from_defaults(vector_store=vs)
    files = [f for f in os.listdir(DOCS) if not f.startswith(".")]
    docs = SimpleDirectoryReader(DOCS).load_data() if files else []
    return VectorStoreIndex.from_documents(docs, storage_context=storage)

index = build()
app = FastAPI()

class Q(BaseModel):
    query: str

@app.get("/health")
def health():
    return {"ok": True}

@app.post("/reindex")
def reindex():
    global index
    index = build()
    return {"ok": True}

@app.post("/query")
def query(q: Q):
    return {"response": str(index.as_query_engine().query(q.query))}
PYEOF
